import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry – size chosen to fit typical label aspect ratio
  const planeGeom = new PlaneGeometry(2, 1);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(planeGeom, material);
  root.add(plane);

  // Load texture (if any) and apply to material
  let loadedTexture = null;
  if (config?.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Create text objects from config
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const color = config?.visualSpec?.colors?.paper ?? '#e8ecf2';
    const txtObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly above the plane (z offset)
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose texture
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // Dispose material and geometry
    material.dispose();
    planeGeom.dispose();
    // Dispose any child objects (e.g., text)
    root.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
    // Kill any GSAP timelines that might have been created
    gsap.globalTimeline.clear();
  };

  return root;
}
